            const toast = document.getElementById('toast');

            const clientNameInput = document.getElementById('clientName');
            const originalScopeInput = document.getElementById('originalScope');
            const hourlyRateInput = document.getElementById('hourlyRate');

            const riskBadge = document.getElementById('riskBadge');
            const outHours = document.getElementById('outHours');
            const outCost = document.getElementById('outCost');
            const clientNote = document.getElementById('clientNote');

            let toastTimeout;

            // Initial row configuration mapping values to human text
            const riskMap = {
                "1": "Low",
                "1.25": "Med",
                "1.5": "High"
            };

            // Inject an editable line item row row logic safely with vanilla elements
            function createLineItemRow(description = "", hours = "5", risk = "1.25") {
                const row = document.createElement('div');
                row.className = 'line-item-row';

                const descInput = document.createElement('input');
                descInput.type = 'text';
                descInput.placeholder = 'e.g., Custom user dashboard';
                descInput.value = description;
                descInput.className = 'item-desc';

                const hoursInput = document.createElement('input');
                hoursInput.type = 'number';
                hoursInput.min = '0';
                hoursInput.value = hours;
                hoursInput.className = 'item-hours';

                const riskSelect = document.createElement('select');
                riskSelect.className = 'item-risk';

                Object.keys(riskMap).forEach(val => {
                    const option = document.createElement('option');
                    option.value = val;
                    option.textContent = riskMap[val];
                    if(val === risk) option.selected = true;
                    riskSelect.appendChild(option);
                });

                const deleteBtn = document.createElement('button');
                deleteBtn.type = 'button';
                deleteBtn.className = 'btn-danger';
                deleteBtn.textContent = '×';
                deleteBtn.addEventListener('click', function() {
                    row.remove();
                });

                row.appendChild(descInput);
                row.appendChild(hoursInput);
                row.appendChild(riskSelect);
                row.appendChild(deleteBtn);

                lineItemsContainer.appendChild(row);
