                const clientName = clientNameInput.value.trim() || 'Project';
                const originalScope = originalScopeInput.value.trim() || 'As previously outlined';
                const hourlyRate = parseFloat(hourlyRateInput.value) || 0;

                const targetRows = lineItemsContainer.querySelectorAll('.line-item-row');

                let combinedRawHours = 0;
                let combinedCalculatedHours = 0;
                let textItemsList = [];

                targetRows.forEach(row => {
                    const desc = row.querySelector('.item-desc').value.trim() || 'Additional Feature Modification';
                    const baseHours = parseFloat(row.querySelector('.item-hours').value) || 0;
                    const multiplier = parseFloat(row.querySelector('.item-risk').value) || 1;

                    const evaluatedItemHours = Math.round((baseHours * multiplier) * 10) / 10;

                    combinedRawHours += baseHours;
                    combinedCalculatedHours += evaluatedItemHours;

                    textItemsList.push(`• ${desc}: ~${evaluatedItemHours} hours`);
                });

                // Fail-safe handling for empty requests list
                if(textItemsList.length === 0) {
                    textItemsList.push('• General scope modifications');
                }

                const finalCost = Math.round(combinedCalculatedHours * hourlyRate);

                // Update UI numerical metrics
                outHours.textContent = combinedCalculatedHours.toFixed(1) + ' hrs';
                outCost.textContent = '$' + finalCost.toLocaleString();

                // Dynamic Risk Badge Assignment Metrics Logic
                // Evaluated using the average risk weight added across inputs
                const aggregateRiskFactor = combinedRawHours > 0 ? (combinedCalculatedHours / combinedRawHours) : 1;

                riskBadge.className = 'risk-badge'; // reset class
                if (aggregateRiskFactor <= 1.1) {
                    riskBadge.textContent = 'Low Risk';
                    riskBadge.classList.add('risk-low');
                } else if (aggregateRiskFactor <= 1.35) {
                    riskBadge.textContent = 'Medium Risk';
                    riskBadge.classList.add('risk-med');
                } else {
                    riskBadge.textContent = 'High Risk';
                    riskBadge.classList.add('risk-high');
                }

                // Construct Note Structure
                const noteText = `Hi Team,\n\nThanks for reaching out about adding these features to ${clientName}.\n\nTo ensure we maintain the timeline and quality of the original agreement (${originalScope}), we will treat these additions as a formal change order:\n\n${textItemsList.join('\n')}\n\nSummary total for scope update:\n• Total Estimated Effort: ${combinedCalculatedHours.toFixed(1)} hours\n• Total Additional Cost: $${finalCost.toLocaleString()}\n\nIf you would like to proceed with modifying the scope to include these items, let me know and I will send over an updated project addendum.\n\nBest regards,`;

                clientNote.value = noteText;
                outputSection.classList.remove('hidden');
            }

            // Clipboard Action
            function copyToClipboard() {
                clientNote.select();
                clientNote.setSelectionRange(0, 99999);

                try {
                    navigator.clipboard.writeText(clientNote.value);
                    showToast('Note copied to clipboard!');
                } catch (err) {
                    showToast('Failed to copy text.');
                }
            }

            // File Export Action
            function exportAsFile() {
                const text = clientNote.value;
                const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
                const url = URL.createObjectURL(blob);

                const cleanName = (clientNameInput.value.trim() || 'Project')
                    .replace(/[^a-z0-9]/gi, '_')
                    .toLowerCase();

                const link = document.createElement('a');
                link.href = url;
                link.download = `change_order_${cleanName}.txt`;
                document.body.appendChild(link);
                link.click();

                document.body.removeChild(link);
                URL.revokeObjectURL(url);
                showToast('TXT file downloaded successfully.');
            }

            // Feedback Display
            function showToast(message) {
                clearTimeout(toastTimeout);
                toast.textContent = message;
                toast.classList.remove('hidden');
                toastTimeout = setTimeout(() => {
                    toast.classList.add('hidden');
                }, 2500);
            }

            // Initialize App Event Listeners
            calcBtn.addEventListener('click', calculateChangeOrder);
            copyBtn.addEventListener('click', copyToClipboard);
            exportBtn.addEventListener('click', exportAsFile);
            addItemBtn.addEventListener('click', function() {
                createLineItemRow();
            });

            // Populate document with an initial item structure default row configuration
            createLineItemRow("Custom User Dashboard", "8", "1.25");

        })();
    </script>
</body>
</html>

